// The mod handler of the `start-cost` slice. It makes no model call, so `requests` is 0.
// `command.run` answers the typed command `/start-cost` by running the CLI `dotclaude-start` and showing its output.
// The skill stays for a call of the model, and for arguments that need a shell.

import {
  failedText,
  outputOf,
  wordsOf,
} from "../../../kernel/skill-command.ts";
import type { Handler } from "../../../kernel/slice.ts";

/** The time that the CLI may take, in milliseconds. */
const TIMEOUT_MS = 120_000;

/** Runs `dotclaude-start` with the words of the command and gives the output as the answer of the command. */
export const onStartCost: Handler<"command.run"> = async ($, e, next) => {
  const words = wordsOf(e.args);
  if (words === undefined) return next(e);
  try {
    const run = await $.process.run(
      [
        "bun",
        "--no-env-file",
        `${$.plugin.root}/bin/dotclaude-start`,
        ...words,
      ],
      { timeoutMs: TIMEOUT_MS },
    );
    return { text: outputOf(run) };
  } catch (error) {
    // The catch has no narrower test, because `$.process.run` documents no error type.
    return { text: failedText("dotclaude-start", error) };
  }
};
